def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re
    import sys

    sys.setrecursionlimit(max(sys.getrecursionlimit(), 1000000))

    token_pattern = re.compile(r"\s*(\d+|[A-Z][A-Z0-9]*|<>|<=|>=|[+\-*/(),:=<>])")
    values = {}
    active = set()

    def parse(text):
        tokens = token_pattern.findall(text)
        pos = 0

        def expression():
            nonlocal pos
            node = term()
            while pos < len(tokens) and tokens[pos] in ("+", "-"):
                op = tokens[pos]
                pos += 1
                node = (op, node, term())
            return node

        def term():
            nonlocal pos
            node = unary()
            while pos < len(tokens) and tokens[pos] in ("*", "/"):
                op = tokens[pos]
                pos += 1
                node = (op, node, unary())
            return node

        def unary():
            nonlocal pos
            if tokens[pos] == "-":
                pos += 1
                return ("neg", unary())
            return atom()

        def atom():
            nonlocal pos
            token = tokens[pos]
            pos += 1

            if token.isdigit():
                return ("number", int(token))
            if token == "(":
                node = expression()
                pos += 1
                return node
            if token == "IF":
                pos += 1  # (
                left = expression()
                op = tokens[pos]
                pos += 1
                right = expression()
                pos += 1  # ,
                then = expression()
                pos += 1  # ,
                otherwise = expression()
                pos += 1  # )
                return ("if", op, left, right, then, otherwise)
            if token in ("SUM", "MIN", "MAX"):
                pos += 1  # (
                args = []
                while True:
                    if pos + 1 < len(tokens) and tokens[pos + 1] == ":":
                        start = tokens[pos]
                        end = tokens[pos + 2]
                        pos += 3
                        args.append(("range", start, end))
                    else:
                        args.append(expression())
                    if tokens[pos] == ")":
                        pos += 1
                        break
                    pos += 1  # ,
                return ("function", token, args)
            return ("cell", token)

        return expression()

    def evaluate_cell(name):
        if name not in cells:
            return 0
        if name in values:
            return values[name]
        if name in active:
            return "#CYCLE!"

        active.add(name)
        content = cells[name]
        if content.startswith("="):
            result = evaluate(parse(content[1:]))
        else:
            result = int(content)
        active.remove(name)
        values[name] = result
        return result

    def evaluate(node):
        kind = node[0]

        if kind == "number":
            return node[1]
        if kind == "cell":
            return evaluate_cell(node[1])
        if kind == "neg":
            value = evaluate(node[1])
            return value if isinstance(value, str) else -value

        if kind == "if":
            left = evaluate(node[2])
            if isinstance(left, str):
                return left
            right = evaluate(node[3])
            if isinstance(right, str):
                return right
            op = node[1]
            if op == "=":
                condition = left == right
            elif op == "<>":
                condition = left != right
            elif op == "<":
                condition = left < right
            elif op == "<=":
                condition = left <= right
            elif op == ">":
                condition = left > right
            else:
                condition = left >= right
            return evaluate(node[4] if condition else node[5])

        if kind == "function":
            function = node[1]
            result = None
            for arg in node[2]:
                if arg[0] == "range":
                    start, end = arg[1], arg[2]
                    col1, col2 = sorted((ord(start[0]), ord(end[0])))
                    row1, row2 = sorted((int(start[1:]), int(end[1:])))
                    for row in range(row1, row2 + 1):
                        for col in range(col1, col2 + 1):
                            name = chr(col) + str(row)
                            if name not in cells:
                                continue
                            value = evaluate_cell(name)
                            if isinstance(value, str):
                                return value
                            if result is None:
                                result = value
                            elif function == "SUM":
                                result += value
                            elif function == "MIN":
                                result = min(result, value)
                            else:
                                result = max(result, value)
                else:
                    value = evaluate(arg)
                    if isinstance(value, str):
                        return value
                    if result is None:
                        result = value
                    elif function == "SUM":
                        result += value
                    elif function == "MIN":
                        result = min(result, value)
                    else:
                        result = max(result, value)
            return 0 if result is None else result

        left = evaluate(node[1])
        if isinstance(left, str):
            return left
        right = evaluate(node[2])
        if isinstance(right, str):
            return right

        if kind == "+":
            return left + right
        if kind == "-":
            return left - right
        if kind == "*":
            return left * right
        if right == 0:
            return "#DIV/0!"
        quotient = abs(left) // abs(right)
        return -quotient if (left < 0) != (right < 0) else quotient

    for name in cells:
        evaluate_cell(name)
    return {name: values[name] for name in cells}
